namespace WebAuthn.Net.Configuration.Options.AttestationStatements;

/// <summary>
///     Options that define behavior when working with <a href="https://www.w3.org/TR/webauthn-3/#sctn-tpm-attestation">"TPM" attestation format</a>.
/// </summary>
public class TpmAttestationStatementOptions
{
    /// <summary>
    ///     A flag controlling if the <a href="https://www.w3.org/TR/webauthn-3/#relying-party">Relying Party</a> wants to accept only credential keys bound to the TPM: generated by the TPM and unable to leave it. Defaults to <see langword="true" />.
    /// </summary>
    /// <remarks>
    ///     A credential key is bound to the TPM when fixedTPM, fixedParent and sensitiveDataOrigin are all SET in the objectAttributes of the 'pubArea' of the attestation statement.
    ///     WebAuthn L3 §8.3 doesn't evaluate them, but a key that was imported into the TPM or loaded into it with TPM2_LoadExternal(), whose private part the client may hold,
    ///     is certified by the TPM exactly like a key that the TPM generated, so it would otherwise get the AttCA attestation of a key that cannot leave the TPM.
    ///     When it is <see langword="true" />, the attestation statement with such a key is rejected. When it is <see langword="false" />, it is accepted.
    ///     A warning is logged and the anomaly is counted in both cases.
    /// </remarks>
    public bool AcceptOnlyTpmBoundKeys { get; set; } = true;
}
